def roman_to_int(s: str) -> int:
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    result = 0
    i = 0

    while i < len(s):
        # If current character is 'I' and next is 'V' or 'X', handle subtraction
        if s[i] == 'I':
            if i + 1 < len(s) and s[i + 1] in 'VX':
                result += roman_values[s[i + 1]] - 1
                i += 2
            else:
                result += 1
                i += 1
        # If current character is 'X' and next is 'L' or 'C', handle subtraction
        elif s[i] == 'X':
            if i + 1 < len(s) and s[i + 1] in 'LC':
                result += roman_values[s[i + 1]] - 10
                i += 2
            else:
                result += 10
                i += 1
        # If current character is 'C' and next is 'D' or 'M', handle subtraction
        elif s[i] == 'C':
            if i + 1 < len(s) and s[i + 1] in 'DM':
                result += roman_values[s[i + 1]] - 100
                i += 2
            else:
                result += 100
                i += 1
        else:
            result += roman_values[s[i]]
            i += 1

    return result
