def format_bytes(n: int) -> str:
    units = ['B', 'KiB', 'MiB', 'GiB']
    if n < 1024:
        return f"{n} {units[0]}"
    for i, unit in enumerate(units[1:], 1):
        if n < 1024 ** i:
            value = n / (1024 ** (i - 1))
            return f"{value:.1f} {unit}"
    return f"{n / (1024 ** 4):.1f} GiB"
