def gcd_list(nums: list) -> int:
    from math import gcd
    from functools import reduce

    # Handle the case where all numbers are zero
    if all(n == 0 for n in nums):
        return 0

    # Use reduce to compute GCD of the entire list
    result = nums[0]
    for i in range(1, len(nums)):
        result = gcd(result, nums[i])
        # If result becomes 1, no further changes will help
        if result == 1:
            break

    return abs(result)
